package com.spai.portal.task.controller;import java.util.*;import javax.validation.Valid;import javax.validation.constraints.NotBlank;import com.spai.portal.common.ApiResponse;import com.spai.portal.security.PortalPrincipal;import com.spai.portal.task.domain.TaskProgress;import com.spai.portal.task.service.TaskService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/tasks")public class TaskController{private final TaskService service;public TaskController(TaskService service){this.service=service;}@GetMapping public ApiResponse<Map<String,Object>>list(@RequestParam Map<String,String>filters,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(service.list(filters,Math.max(page,0),Math.min(Math.max(size,1),200)));}@PutMapping("/{taskId}/progress/{teamId}")public ApiResponse<TaskProgress>update(@PathVariable String taskId,@PathVariable String teamId,@Valid @RequestBody Update req,@AuthenticationPrincipal PortalPrincipal p){boolean admin=p.getAuthorities().stream().anyMatch(a->"ROLE_ADMIN".equals(a.getAuthority()));return ApiResponse.ok(service.update(taskId,teamId,req.status,req.lockVersion,p.getUserId(),p.getTeamId(),admin));}public static class Update{@NotBlank public String status;public long lockVersion;}}
